/**
 * Performs a right node rotation.
 * @param node a node to rotate
 * @return a new parent of the {@code node}
 */
private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) {
        throw new IllegalArgumentException("Cannot rotate a null node");
    }
    if (node.getLeft() == null) {
        throw new IllegalArgumentException("Node does not have a left child");
    }
    TreeNode<T> left = node.getLeft();
    TreeNode<T> parent = node.getParent();
    TreeNode<T> grandParent = parent.getParent();
    left.setParent(grandParent);
    if (grandParent != null) {
        grandParent.setRight(left);
    }
    parent.setLeft(left.getRight());
    if (left.getRight() != null) {
        left.getRight().setParent(parent);
    }
    left.setRight(parent);
    node.setParent(null);
    return left;
}

