    if (desiredCapacity < 2) {
        return 2;
    }

    // Find the next prime number that is greater than or equal to the desired capacity
    boolean isPrime = false;
    int prime = 3;
    while (!isPrime) {
        isPrime = true;
        for (int i = 2; i <= Math.sqrt(prime); i++) {
            if (prime % i == 0) {
                isPrime = false;
                break;
            }
        }
        prime += 2;
    }

    // Return the calculated prime number
    return prime;
}
