    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Check if the relative path has more components than the path
    if (relativePathComponents.length > pathComponents.length) {
        throw new IllegalArgumentException("Relative path has more components than the path");
    }

    // Create a new path by combining the path and relative path
    String newPath = "";
    for (int i = 0; i < relativePathComponents.length; i++) {
        if (relativePathComponents[i].equals("..")) {
            if (i > 0) {
                newPath = pathComponents[i - 1] + "/" + newPath;
            } else {
                throw new IllegalArgumentException("Cannot go above the root directory");
            }
        } else {
            newPath = pathComponents[i] + "/" + newPath;
        }
    }

    // Remove any trailing slashes
    while (newPath.endsWith("/")) {
        newPath = newPath.substring(0, newPath.length() - 1);
    }

    return newPath;
