import java.io.File;
import java.io.IOException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Invalid input");
    }

    List<String> lines = Files.lines(file.toPath()).collect(Collectors.toList());
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    for (String line : lines) {
        String[] tokens = line.split(",");
        if (tokens.length != 4) {
            continue; // invalid line
        }

        long threadId = Long.parseLong(tokens[0]);
        String threadName = tokens[1];
        Instant time = Instant.parse(tokens[2]);
        String state = tokens[3];

        ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadId, threadName, time, state);

        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            if (timeRange.contains(time)) {
                threadSnapshots.add(threadSnapshot);
                break;
            }
        }
    }

    return threadSnapshots;
}
